using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

// Check build result
Console.WriteLine($"Build Succeeded: {build.Succeeded}");
Console.WriteLine();

// Find all errors
var errors = build.FindChildrenRecursive<Error>();
Console.WriteLine("=== ALL ERRORS ===");
foreach (var e in errors)
{
    var node = (BaseNode)e.Parent;
    string projectName = "unknown";
    while (node != null)
    {
        if (node is Project p) { projectName = p.Name; break; }
        node = node.Parent as BaseNode;
    }
    Console.WriteLine($"  Project: {projectName}");
    Console.WriteLine($"  File: {e.File}:{e.LineNumber}:{e.ColumnNumber}");
    Console.WriteLine($"  {e.Code}: {e.Text}");
    Console.WriteLine();
}

// Find all build messages containing "failed" or "error"
var messages = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && (m.Text.Contains("failed") || m.Text.Contains("FAILED")));
Console.WriteLine("=== FAILURE MESSAGES ===");
foreach (var m in messages)
    Console.WriteLine($"  {m.Text}");

// Check project references
Console.WriteLine("\n=== PROJECT FILES ===");
Console.WriteLine("Services.csproj references Core.csproj");
Console.WriteLine("Api.csproj references Services.csproj and Core.csproj");
